import{_ as o,o as d,c,ah as a}from"./chunks/framework.ojwJKwrc.js";const u=JSON.parse('{"title":"SystemVerilog リファレンス","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"ja/guide/systemverilog-reference.md","filePath":"ja/guide/systemverilog-reference.md"}'),t={name:"ja/guide/systemverilog-reference.md"};function r(i,e,l,s,n,p){return d(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="systemverilog-リファレンス" tabindex="-1">SystemVerilog リファレンス <a class="header-anchor" href="#systemverilog-リファレンス" aria-label="Permalink to &quot;SystemVerilog リファレンス&quot;">​</a></h1><p>導入と最初のシミュレーションは <a href="./systemverilog.html">SystemVerilog サポート</a>を参照してください。 このページでは、個々の構文の対応範囲、制約、実行時の挙動を説明します。</p><h2 id="what-is-supported" tabindex="-1">構文の対応範囲 <a class="header-anchor" href="#what-is-supported" aria-label="Permalink to &quot;構文の対応範囲 {#what-is-supported}&quot;">​</a></h2><p>同期 RTL を記述する、合成向けの SystemVerilog が対象で、デザインレベルでテストします。</p><h3 id="構造と接続" tabindex="-1">構造と接続 <a class="header-anchor" href="#構造と接続" aria-label="Permalink to &quot;構造と接続&quot;">​</a></h3><table tabindex="0"><thead><tr><th>領域</th><th>サポート内容</th></tr></thead><tbody><tr><td>モジュール</td><td>ANSI ポート、<code>parameter</code> / <code>localparam</code>、型パラメータ（<code>parameter type</code>）、名前付き・位置指定のポート／パラメータ接続、階層、インスタンス配列（接続は全要素に共通、または全要素の幅に等しければ要素ごとに分割）</td></tr><tr><td>generate</td><td><code>for</code>（<code>genvar</code>）、<code>if</code>、<code>case</code>。<code>**</code> を含む定数式</td></tr><tr><td>package</td><td>型、パラメータ、enum、関数。<code>import p::*;</code>、<code>import p::x;</code>、<code>p::x</code> で参照</td></tr><tr><td>interface</td><td>値・型パラメータ、ヘッダーの package import、メンバー、内部ロジックと関数、入れ子の interface インスタンス、インスタンス配列、定数添字で選ぶ配列要素の関数呼び出し、modport 付き・なしのポート、generic interface ポート、interface ポート配列。明示・暗黙の名前付き接続（<code>.bus(bus)</code> / <code>.bus</code>）、<code>input</code> / <code>output</code> modport と imported function。詳しい制約は下記参照</td></tr></tbody></table><h3 id="データと式" tabindex="-1">データと式 <a class="header-anchor" href="#データと式" aria-label="Permalink to &quot;データと式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>領域</th><th>サポート内容</th></tr></thead><tbody><tr><td>型</td><td><code>logic</code>、<code>bit</code>、<code>reg</code>、packed ベクタ、任意の定数境界と昇順・降順の多次元 packed 配列、packed 構造体、hard packed untagged union、enum（暗黙値を含む）、<code>typedef</code>、メモリとして使う unpacked 配列、符号付き・符号なし</td></tr><tr><td>式</td><td><code>**</code> を含む算術、論理、シフト、比較、リダクション、連結・複製、<code>?:</code>、<code>inside</code>、<code>==?</code> / <code>!=?</code>、キャスト（<code>N&#39;(x)</code>、<code>signed&#39;(x)</code>、<code>T&#39;(x)</code>）、<code>$signed</code> / <code>$unsigned</code></td></tr><tr><td>選択</td><td>定数・実行時のビット選択と indexed part-select（<code>[i]</code>、<code>[i +: W]</code>、<code>[i -: W]</code>）。読み書きの両方、宣言の向きによらず</td></tr><tr><td>パターン</td><td>packed 構造体・packed 配列・unpacked 配列の assignment pattern（<code>&#39;{a, b}</code>、<code>&#39;{x: a, default: 0}</code>、<code>&#39;{n{a}}</code>、<code>T&#39;{...}</code>）</td></tr><tr><td>クラス</td><td>モジュール内で宣言したクラス。64 ビット以下の 2 値整数型・<code>string</code>・クラスハンドル型のプロパティ（初期値つきも可）、引数あり・なしの <code>new</code>、暗黙と明示のコンストラクタ、ハンドル経由またはクラス内から修飾なしで呼ぶメソッド（<code>function</code> と <code>task</code>、本体をクラス外に書く <code>extern</code> も可）、<code>this</code>、<code>null</code>、ハンドルの代入と比較、プロパティとメソッドの継承（基底クラスのコンストラクタは <code>super.new(...)</code> か <code>extends Base(...)</code> で呼ぶ）、<code>super.</code> によるメンバ参照、virtual メソッド、抽象クラス（<code>virtual class</code>）と pure virtual メソッド、interface クラスを実装するクラスと interface クラスのハンドルを通したメソッド呼び出し、関数とタスクとしてのクラスハンドルの <code>$cast</code>、static プロパティとメソッド、static メンバと <code>C::new</code> の <code>C::</code> によるスコープ解決、ハンドルの配列。<a href="#classes">クラス</a>を参照</td></tr><tr><td>文字列</td><td><code>string</code> 型の変数、関数の引数と戻り値。文字列・文字列リテラル・キャスト（<code>string&#39;(x)</code>）の代入、<code>==</code> / <code>!=</code> と大小比較、連結と複製（実行時の回数も可）、文字の読み書き（<code>s[i]</code>）、メソッド <code>len</code>、<code>getc</code>、<code>putc</code>、<code>toupper</code>、<code>tolower</code>、<code>compare</code>、<code>icompare</code>、<code>substr</code>、<code>atoi</code> / <code>atohex</code> / <code>atooct</code> / <code>atobin</code>、<code>itoa</code> / <code>hextoa</code> / <code>octtoa</code> / <code>bintoa</code>。<code>%s</code> と書式なしの表示。<a href="#strings">文字列</a>を参照</td></tr><tr><td>パラメータ</td><td>整数のパラメータ、128ビットを超える幅と X/Z を保持するパラメータ上書き、assignment pattern で与える unpacked 配列型・packed 構造体型のパラメータ（定数テーブル）と unpacked 配列のパターンによる上書き</td></tr></tbody></table><h3 id="プロセスと制御" tabindex="-1">プロセスと制御 <a class="header-anchor" href="#プロセスと制御" aria-label="Permalink to &quot;プロセスと制御&quot;">​</a></h3><table tabindex="0"><thead><tr><th>領域</th><th>サポート内容</th></tr></thead><tbody><tr><td>連続論理</td><td><code>assign</code>、<code>wire w = expr;</code></td></tr><tr><td>組み合わせプロセス</td><td><code>always_comb</code>、<code>always @*</code>、ブロッキング代入の <code>always_latch</code>、ブロックローカル変数、逐次・依存するブロッキング代入、プロセスが書き込む前の変数の読み出し（直前の値）</td></tr><tr><td>順序プロセス</td><td><code>always_ff @(posedge clk)</code>、<code>always @(posedge clk or negedge rst_n)</code> など。ブロッキング・ノンブロッキング代入、連結を代入先とする代入、4 値のクロック・リセット信号、複数のクロックドメインで共有する非同期リセット、同一クロック・同一リセットの両エッジを使うプロセス、あるプロセスのクロックを別のプロセスの非同期リセットとして使う信号（時間付きの <code>Simulation</code> はすべてのエッジを実行します。<code>Simulator::tick</code> はイベントの立ち上がりエッジだけです）</td></tr><tr><td>initial ブロック</td><td><code>initial</code> ブロックと変数宣言の初期化子（<code>logic [7:0] v = 8&#39;h5a;</code>、interface のメンバーを含む）。初期化子は <code>initial</code> ブロックより先に適用。書き込む値が定数のもの（定数の <code>if</code> / <code>for</code>、<code>$readmemh</code> / <code>$readmemb</code> を含む）は初期状態を定める。デザインの状態を読むものやシステムタスクを呼ぶものなどそれ以外は、時間を持つ <code>Simulation</code> で時刻 0 からプロセスとして実行（<code>Simulator</code> はプロセスを実行しないため、このようなデザインでは <code>SimulatorErrorKind::ProcessRequiresSimulation</code> でビルドに失敗）</td></tr><tr><td>文</td><td><code>if</code> / <code>else</code>、<code>case</code>、<code>casez</code>、<code>casex</code>、<code>case ... inside</code>、<code>unique</code> / <code>priority</code>、<code>for</code>、<code>while</code>、<code>do ... while</code>、<code>repeat</code>、<code>forever</code>、<code>foreach</code>（反復回数が定数なら展開し、そうでなければ実行時に実行）、<code>break</code> / <code>continue</code> / <code>return</code>、即時アサーション</td></tr><tr><td>関数</td><td><code>input</code> / <code>output</code> / <code>inout</code> 引数を持てる <code>function</code> と、<code>task</code>。<code>return</code>、または関数名への代入で値を返す。ローカル変数と <code>localparam</code>、部分選択や複合的な代入先への代入。呼び出しはインライン展開。定数式（パラメータ、範囲）の中の定数引数による呼び出しはエラボレーション時に評価</td></tr></tbody></table><h3 id="timing-controls" tabindex="-1">タイミング制御 <a class="header-anchor" href="#timing-controls" aria-label="Permalink to &quot;タイミング制御 {#timing-controls}&quot;">​</a></h3><p>時間を持つ <code>Simulation</code> では、<code>initial</code> と通常の <code>always</code> のプロセスが中断できます。</p><table tabindex="0"><thead><tr><th>制御</th><th>対応範囲</th></tr></thead><tbody><tr><td><code>#delay</code></td><td>整数と実数の遅延、<code>#(min:typ:max)</code>（typ の値）、<a href="#time-literal-delays">時間リテラル</a>。X / Z の遅延は 0 として扱う</td></tr><tr><td><code>@(...)</code></td><td>変数、<code>posedge</code> / <code>negedge</code> / <code>edge</code>、<code>or</code> または <code>,</code> で並べた項目、ビット選択・部分選択・実行時添字の選択、pure な関数呼び出しを含む任意の式、文が読む変数を待つ <code>@*</code> / <code>@(*)</code></td></tr><tr><td><code>wait (condition)</code></td><td>任意の条件。X / Z の条件は偽として扱う</td></tr><tr><td>代入</td><td>ブロッキング代入とノンブロッキング代入。ノンブロッキング代入はそのタイムスロットの NBA 領域で反映</td></tr></tbody></table><p>文が読む変数をちょうど並べたセンシティビティリスト（<code>@*</code> が求めるもの、IEEE 1800-2023 9.4.2.2）を持つ <code>always</code> は、<code>always @(a or b) y = a + b;</code> や <code>always @(b, a) y = a + b;</code> のように、 <code>Simulator</code> でも <code>Simulation</code> でも <code>always @*</code> と同様にシミュレーションします。 文にはタイミング制御とノンブロッキング代入を含められません。エッジを持たないそれ以外の センシティビティリストを持つ <code>always</code> はプロセスとして実行します。<code>always @(a) y = a + b;</code> は <code>b</code> だけが変化しても <code>y</code> を更新しません。<code>always @*</code> として扱うと他の論理と組み合わせループを作るリストも プロセスとして実行します。フリップフロップの形をしていないエッジ駆動の <code>always</code> も同様です。 選択や式のエッジ（<code>@(posedge v[0])</code>、<code>@(posedge (a &amp; b))</code>）、<code>edge</code>、エッジと並んだエッジなしの項目、 複数ビットのエッジ信号（最下位ビットでエッジを判定）、本体がどれも非同期リセットとして判定しない 複数のエッジを持つものがこれに当たります。この形でなければならないのは <code>always_ff</code> だけです。 <code>Simulator</code> はプロセスを実行しないため、このようなデザインでは <code>SimulatorErrorKind::ProcessRequiresSimulation</code> でビルドに失敗します。<code>Simulation</code> を使うか、 <code>always @*</code> / <code>always_comb</code> で記述してください。</p><h3 id="時間待ちを含む-task" tabindex="-1">時間待ちを含む task <a class="header-anchor" href="#時間待ちを含む-task" aria-label="Permalink to &quot;時間待ちを含む task&quot;">​</a></h3><p><code>initial</code> と通常の <code>always</code> から、<code>#delay</code>・<code>@(event)</code>・<code>wait (condition)</code> を 含む task を呼び出せます。task のネストも可能です。呼び出しは呼び出し元の状態機械に インライン展開されます。エッジ待ちの <code>always</code> は task の完了後に次のエッジを待ちます。 function・<code>always_comb</code>・<code>always_ff</code> からの時間待ち task 呼び出しは拒否します。 <code>always @*</code> からの呼び出しも現在は拒否します（<a href="https://github.com/celox-sim/celox/issues/1710" target="_blank" rel="noreferrer">#1710</a>）。</p><p>automatic な引数とローカル変数は呼び出しごとに独立し、中断中も保持されます。 module 内の static task の引数は共有されます。input／inout は呼び出し時にコピーされ、output／inout は task 終了時にコピー戻しされます（IEEE 1800-2023 13.3–13.3.2）。時間待ち task の static ローカル宣言は未対応のため、automatic を使ってください。 package／<code>$unit</code> の static 引数を持つ時間待ち task と、static task 引数を読む <code>wait</code> 条件は、 共有ストレージと変更通知に対応するまで拒否します。 イベント式の制約は、プロセスに直接記述するイベント待ちと同じです。</p><h3 id="スコープ変数の乱数化" tabindex="-1">スコープ変数の乱数化 <a class="header-anchor" href="#スコープ変数の乱数化" aria-label="Permalink to &quot;スコープ変数の乱数化&quot;">​</a></h3><p><code>randomize(a, b)</code> と <code>std::randomize(a, b)</code> は、制約なしで packed 変数全体を乱数化します。 符号付きベクタと packed struct を含め、Celox が扱える幅で各ワードに0／1の乱数を設定し、 成功値の1（signed <code>int</code>）を返します。引数なしの場合は変数や乱数列を変更せず成功します。 プロセスごとの永続的な乱数列を使い、文の実行順序と短絡評価に従います （IEEE 1800-2023 18.12）。</p><p><code>with</code> 制約、class メソッド、enum 変数、unpacked 配列、net、定数、 select・連結式の引数は未対応として拒否します。</p><h3 id="time-literal-delays" tabindex="-1">時間リテラルによる遅延 <a class="header-anchor" href="#time-literal-delays" aria-label="Permalink to &quot;時間リテラルによる遅延 {#time-literal-delays}&quot;">​</a></h3><p>遅延制御の時間リテラルは <code>#5ns</code>、<code>#(2.75ns)</code>、<code>#40ps</code> など、<code>fs</code> から <code>s</code> の6単位に 対応します。宣言スコープの時間精度で丸めてから scheduler の tick に変換します （5.8、3.14.1）。<code>#1.5</code> や <code>#r</code> などの実数の遅延も同様に丸め、ちょうど中間の値は 0 から遠い方に 丸めます（6.12.1）。負の遅延は2の補数として待ち（9.4.1）、NaN の遅延は 0 として扱います。</p><h3 id="組み込み関数とタスク" tabindex="-1">組み込み関数とタスク <a class="header-anchor" href="#組み込み関数とタスク" aria-label="Permalink to &quot;組み込み関数とタスク&quot;">​</a></h3><table tabindex="0"><thead><tr><th>領域</th><th>サポート内容</th></tr></thead><tbody><tr><td>システム関数</td><td><code>$timeunit</code>、<code>$timeprecision</code>、<code>$bits</code>、<code>$size</code>、<code>$clog2</code>、<code>$countbits</code>、<code>$countones</code>、<code>$onehot</code>、<code>$onehot0</code>、<code>$isunknown</code>、<code>$isunbounded</code> は式・定数式の中と文として。<code>$signed</code>、<code>$unsigned</code> は式の中と文として</td></tr><tr><td>乱数</td><td><code>$urandom</code>、<code>$urandom_range</code>、<code>$random</code>、<code>$dist_uniform</code> はクロックで起動するプロセス、<code>always_comb</code>、<code>always @*</code>、<code>initial</code> とそれらから呼ぶサブルーチンで使用可能。<code>$urandom</code> の任意の整数式によるシード、<code>$random</code> のシード変数、プロセスごとに独立した乱数列</td></tr><tr><td>シミュレーション時刻</td><td><code>$time</code>、<code>$stime</code>、<code>$realtime</code> はクロックで起動するプロセス、組合せプロセス、継続代入、<code>initial</code> とそれらから呼ぶサブルーチンで使用可能</td></tr><tr><td>システムタスク</td><td><code>always</code> 系のプロセスとサブルーチンの <code>$printtimescale</code>、<code>$display</code>、<code>$write</code> とその <code>b</code> / <code>o</code> / <code>h</code> 形、<code>$error</code>、<code>$warning</code>、<code>$info</code>、<code>$fatal</code>、<code>$finish</code>、<code>$stop</code>、<code>$exit</code>。<code>initial</code> ブロックでも使えます。<code>$readmemh</code> / <code>$readmemb</code> はそれらと <code>initial</code> ブロック。Veryl の <code>$assert</code> と <code>$assert_continue</code></td></tr><tr><td>実行時 I/O</td><td><code>$test$plusargs</code>、<code>$value$plusargs</code>、<code>$fopen</code>、<code>$fclose</code>、<code>$fdisplay</code> / <code>$fwrite</code> と基数指定形、<code>$writememh</code> / <code>$writememb</code>、<a href="./vcd.html#systemverilog-source-controls">VCD 制御</a>。時間を持つプロセスで実行</td></tr><tr><td>状態</td><td>2 値・4 値シミュレーション</td></tr></tbody></table><p>上記の各構文は、ソフトウェアモデルと結果を比較するテストで確認しています。Veryl が出力する SystemVerilog に対しても、共有の Veryl 適合性スイートを実行しています。</p><h2 id="what-is-not-supported" tabindex="-1">未対応の構文 <a class="header-anchor" href="#what-is-not-supported" aria-label="Permalink to &quot;未対応の構文 {#what-is-not-supported}&quot;">​</a></h2><p>未対応の構文は、無視せずに、その構文名を示す <code>Unsupported</code> エラーを返します。エラーには その構文を追跡する issue の番号が含まれます。専用の issue がない構文は、フロントエンドの ロードマップ <a href="https://github.com/celox-sim/celox/issues/88" target="_blank" rel="noreferrer">#88</a> を指します。</p><ul><li><a href="#classes">対応範囲</a>外のクラスの機能：クラスハンドル以外の変数への <code>$cast</code>、interface クラスの typedef とパラメータ、package 内で宣言したクラス、パラメータ付きクラス、名前付きのコンストラクタ引数、浅いコピー（<code>new h</code>）、4 値・<code>real</code>・配列・64 ビットを超えるプロパティ。時間待ちを含む task の static ローカル宣言、再帰呼び出し、<code>ref</code> 引数。</li><li>interface のポート、<code>inout</code> / <code>ref</code> / 式を使う modport、virtual interface など。 interface 自体と入れ子の interface は対応しています。型パラメータはインスタンスごとに解決し、modport ポート経由でも伝搬します。 再帰する特殊化と64段を超える入れ子は拒否します。細かな制約は<a href="/celox/guide/systemverilog-reference.html#interface-restrictions">英語版の一覧</a>を参照してください。</li><li>振る舞い記述・検証向けの構文：<code>final</code>、代入内のタイミング制御（<code>a = #1 b</code>）、遅延付き継続代入（<a href="https://github.com/celox-sim/celox/issues/444" target="_blank" rel="noreferrer">#444</a>）、 named event と <code>-&gt;</code>、<code>fork</code> / <code>join</code>、<code>wait fork</code> / <code>disable fork</code>、並行アサーション、<code>force</code> / <code>release</code>。</li><li>プロセス内のタイミング制御：<code>iff</code> 修飾（<a href="https://github.com/celox-sim/celox/issues/1444" target="_blank" rel="noreferrer">#1444</a>）、 package スコープの遅延値 （<a href="https://github.com/celox-sim/celox/issues/1710" target="_blank" rel="noreferrer">#1710</a>）、イベント式内の impure な関数呼び出し、 static task 引数を読む <code>wait</code> 条件とイベント式。プロセス内のノンブロッキング代入は、 unpacked 配列の要素、実行時に決まる位置、代入先の範囲外の定数位置をまだ代入先にできません （<a href="https://github.com/celox-sim/celox/issues/1709" target="_blank" rel="noreferrer">#1709</a>）。</li><li><code>always_latch</code> 内のノンブロッキング代入（<a href="https://github.com/celox-sim/celox/issues/431" target="_blank" rel="noreferrer">#431</a>）。対応するラッチではブロッキング代入を使用してください。</li><li><code>always_comb</code> の暗黙のラッチ推論はデフォルトで拒否します。<code>celox.toml</code> の <code>[diagnostics]</code> で <code>inferred_latch = &quot;warn&quot;</code> または <code>&quot;allow&quot;</code> を指定すると許可できます。通常の <code>always @*</code> と明示的な <code>always_latch</code> にはこの設定は不要です。</li><li>ポートとインスタンス：non-ANSI 形式のポート宣言（<a href="https://github.com/celox-sim/celox/issues/426" target="_blank" rel="noreferrer">#426</a>）、<code>ref</code> ポート（<a href="https://github.com/celox-sim/celox/issues/427" target="_blank" rel="noreferrer">#427</a>）、 ワイルドカード接続 <code>.*</code>（<a href="https://github.com/celox-sim/celox/issues/442" target="_blank" rel="noreferrer">#442</a>）、ゲートプリミティブ（<a href="https://github.com/celox-sim/celox/issues/457" target="_blank" rel="noreferrer">#457</a>）、<code>bind</code>。</li><li>宣言：interface 配列のメンバーの変数宣言の初期化子、ANSI ポートの既定値、tagged union、soft packed union、packed union の assignment pattern、ドライバを持たない内部ネット（<a href="https://github.com/celox-sim/celox/issues/460" target="_blank" rel="noreferrer">#460</a>）、unpacked 構造体、<code>real</code>。</li><li>順序回路のプロセス：イベントリストの <code>iff</code> 修飾（<a href="https://github.com/celox-sim/celox/issues/452" target="_blank" rel="noreferrer">#452</a>）、および <code>always_ff</code> での 単純な信号以外のエッジオペランド（<a href="https://github.com/celox-sim/celox/issues/464" target="_blank" rel="noreferrer">#464</a>）、複数ビットのエッジ信号、 非同期リセットを持たない複数のエッジ。</li><li>組み合わせ回路のプロセス：<code>always_comb</code> 内のノンブロッキング代入（<a href="https://github.com/celox-sim/celox/issues/453" target="_blank" rel="noreferrer">#453</a>）。</li><li>ループ：手続き的なループの展開は 10,000 回までです。反復回数が実行時に決まる組み合わせ 回路のループは、カウンタ形式の <code>for</code> である必要があります。loop-generate は 10,000 回を 超えると拒否し（<a href="https://github.com/celox-sim/celox/issues/448" target="_blank" rel="noreferrer">#448</a>）、ビット演算の複合代入による genvar の更新は拒否します （<a href="https://github.com/celox-sim/celox/issues/455" target="_blank" rel="noreferrer">#455</a>）。</li><li>式：ストリーミング連結（<a href="https://github.com/celox-sim/celox/issues/447" target="_blank" rel="noreferrer">#447</a>）、パラメータ式での リダクション演算子（<a href="https://github.com/celox-sim/celox/issues/456" target="_blank" rel="noreferrer">#456</a>）。</li><li>システムタスクとシステム関数：Celox は IEEE 1800-2023 が定義するすべての名前を、 附属書 D の任意のものも含めて知っています。呼び出した位置で対応していないもの（<code>$fgets</code> など）は、 使われていないパラメータや関数本体の中を含め、書かれた 場所にかかわらず名前を示して報告します。システムタスクでもシステム関数でもない <code>$</code> 名、 引数の数が誤っている呼び出し、既定値のない引数の省略、値として使ったタスクはエラーです。</li><li><a href="#dpi-c-imports">DPI-C の対応範囲</a>を超える機能と DPI export、トライステートバスと複数ドライバ、階層参照。</li></ul><h2 id="semantics-worth-knowing" tabindex="-1">実行時の挙動 <a class="header-anchor" href="#semantics-worth-knowing" aria-label="Permalink to &quot;実行時の挙動 {#semantics-worth-knowing}&quot;">​</a></h2><h3 id="上限なしのパラメータ" tabindex="-1">上限なしのパラメータ <a class="header-anchor" href="#上限なしのパラメータ" aria-label="Permalink to &quot;上限なしのパラメータ&quot;">​</a></h3><p><code>$isunbounded(P)</code> は、値パラメータが <code>$</code> の場合に1、それ以外では0を1ビットの符号なし値として返します。<code>$</code> は別のパラメータへの代入やインスタンスのパラメータ上書きでも保持されます（IEEE 1800-2023 6.20.7、20.6.3）。</p><h3 id="strings" tabindex="-1">文字列 <a class="header-anchor" href="#strings" aria-label="Permalink to &quot;文字列 {#strings}&quot;">​</a></h3><p><code>string</code> 型の変数はシミュレータのヒープ上の文字列への参照を持ちます。代入、等値比較、値の変化の検出は 32 ビット整数と同じコストで、文字列の中身を読む・作る演算だけがランタイムを呼び出します。文字列はタイムスロットの間と各 <code>tick</code> の後に回収されます。IEEE 1800-2023 6.16 のとおり、文字列にするときに NUL バイトは取り除かれ、文字列へ代入・キャストした整数値は最上位のバイトから並びます。</p><p>未対応：<code>$sformat</code> / <code>$sformatf</code>、<code>atoreal</code> / <code>realtoa</code>、<code>$value$plusargs</code>・ファイル I/O・DPI-C の文字列引数、VPI・VCD 出力・TypeScript API での文字列値。</p><h3 id="classes" tabindex="-1">クラス <a class="header-anchor" href="#classes" aria-label="Permalink to &quot;クラス {#classes}&quot;">​</a></h3><p>クラス型の変数はシミュレータのヒープ上のオブジェクトへのハンドルを持ち、コンストラクタを呼ぶまでは <code>null</code> です。文字列と同じく、ハンドルのコピーと比較は 32 ビット整数と同じコストで、プロパティの読み書きとオブジェクトの生成だけがランタイムを呼び出します。どの変数・オブジェクトからも参照されないオブジェクトは、タイムスロットの間と各 <code>tick</code> の後に回収されます。メソッドは呼び出したオブジェクトを受け取るので function でも task でもよく、呼び出しは変数のクラスのメソッドに結び付きます（IEEE 1800-2023 8.6）。virtual メソッドの呼び出しは、代わりにオブジェクトのクラスの override を実行します。ただし <code>super.m(...)</code> は基底クラスの実装を実行します（8.15、8.20）。override はオブジェクトのクラスで選ぶので、ランタイムの呼び出しが 1 回増えます。<code>null</code> を通したプロパティの読み書きやメソッド呼び出しは実行時エラーです。抽象クラスの生成と、pure virtual メソッドを実装しないクラスはエラーになります（8.21）。interface クラスを実装するクラスは、そのメソッドをすべて同じ戻り値型で実装するか、抽象クラスなら pure として宣言し直します（8.26）。interface クラスのハンドルを通して呼んだメソッドは、オブジェクトのクラスの実装を実行します。</p><p>ハンドルは、そのクラス・基底クラス・実装する interface クラスの変数に代入でき、それ以外のハンドルの代入はエラーです（IEEE 1800-2023 8.16、8.26.5）。<code>$cast(dest, source)</code> は、オブジェクトのクラスが <code>dest</code> のクラスを継承または実装するハンドルか <code>null</code> を代入して 1 を返します。それ以外では <code>dest</code> を変えずに 0 を返し、タスクとして呼んだ場合はエラーを報告します。どちらも他方を継承しないクラスどうしの <code>$cast</code> は、ソースが interface クラスでない限り常に失敗します（8.16）。</p><p>コンストラクタは、まず <code>super.new(...)</code> または <code>extends</code> 節の引数で基底クラスのコンストラクタを呼び、次に自クラスが宣言するプロパティの初期値を設定し、最後に本体を実行します（IEEE 1800-2023 8.17）。static プロパティはクラスを宣言したモジュールの変数なので、モジュールのインスタンスごとに 1 つずつあります。</p><p>チェックポイントはオブジェクトを保持します。状態ファイルは文字列を記録しますがオブジェクトは記録しないため、オブジェクトを持つ変数があると状態ファイルの保存は失敗します。</p><h3 id="インスタンス配列の要素" tabindex="-1">インスタンス配列の要素 <a class="header-anchor" href="#インスタンス配列の要素" aria-label="Permalink to &quot;インスタンス配列の要素&quot;">​</a></h3><p>要素は宣言どおりの添字で参照します。<code>Child u[3:2](...)</code> の <code>u[3]</code> には <code>child_signal(&amp;[(&quot;u&quot;, 3)], &quot;y&quot;)</code> や <code>dut.u[3]</code> で届き、添字は <code>InstanceHierarchy::index</code> にも入ります。負の境界を持つ配列は拒否します。</p><h3 id="範囲外の選択" tabindex="-1">範囲外の選択 <a class="header-anchor" href="#範囲外の選択" aria-label="Permalink to &quot;範囲外の選択&quot;">​</a></h3><p>ベクタの端を越える実行時の選択は、足りないビットを <code>X</code>（2 値シミュレーションでは 0） として読み、書き込みは存在するビットだけを更新します。ベクタから一部はみ出す定数の パートセレクトへの書き込みも、手続き代入・継続代入のどちらでも内側のビットだけを更新します。 <code>logic [7:0] q</code> への <code>q[9:6] = v</code> は <code>v[1:0]</code> を <code>q[7:6]</code> に書き込みます。ベクタから 完全に外れた書き込みは何もしません。このような定数のパートセレクトの読み出しと、配列要素や 内側の packed 次元の宣言範囲を越える定数のパートセレクトへの書き込みは拒否します （<a href="https://github.com/celox-sim/celox/issues/88" target="_blank" rel="noreferrer">#88</a>）。</p><h3 id="ワイルドカード比較" tabindex="-1">ワイルドカード比較 <a class="header-anchor" href="#ワイルドカード比較" aria-label="Permalink to &quot;ワイルドカード比較&quot;">​</a></h3><p><code>casez</code>、<code>casex</code>、<code>inside</code>、<code>==?</code> は、定数パターンの <code>?</code>、<code>x</code>、<code>z</code> ビットを、2 値・4 値のどちらのシミュレーションでも尊重します。</p><h3 id="package" tabindex="-1">package <a class="header-anchor" href="#package" aria-label="Permalink to &quot;package&quot;">​</a></h3><p>package はそれぞれ独立したスコープとして 1 回だけ解析し、名前は IEEE 1800-2023 26.3 の規則で解決します。<code>p::x</code> は package <code>p</code> の項目を指すため、複数の package、または package と モジュールに同名の項目があっても衝突しません。<code>import p::x;</code> で見えるのは <code>x</code> だけです。 <code>import p::*;</code> では、スコープ自身の宣言が package の同名の項目を隠し、2 つの wildcard import の package が宣言する名前は、参照したときだけエラーになります。generate ブロック内の import は、そのブロック （と内側のブロック）でだけ名前を見えるようにし、モジュール自身の宣言や import より優先されます。package の関数の中の名前は package の中で解決します。package の変数は、それを使うすべてのモジュール（Veryl からインスタンス化した SystemVerilog モジュールを含む）で共有される 1 つのオブジェクトで、初期化子も反映します。 <code>sim.signal(&quot;p::v&quot;)</code> で参照できます。1 つの package 変数を複数のドライバが書く設計は、書き込む モジュールのインスタンスをすべて数えて拒否します。package 変数のクロック・リセットとしての使用、定数でない package 変数の初期化子、 package の net は未対応です（<a href="https://github.com/celox-sim/celox/issues/1146" target="_blank" rel="noreferrer">#1146</a>）。<code>export</code> 宣言（26.6）は、import した宣言をその package を import する側から見えるようにします。<code>export p::*;</code> が export するのは package が <code>p</code> から実際に import した名前だけです。export を経由した import は元の宣言を指すため、 2 つの経路で同じ宣言を import しても曖昧になりません。<code>q::x</code> は <code>q</code> が <code>x</code> として export する宣言も指します。</p><h3 id="コンパイル単位" tabindex="-1">コンパイル単位 <a class="header-anchor" href="#コンパイル単位" aria-label="Permalink to &quot;コンパイル単位&quot;">​</a></h3><p>ソースファイルはそれぞれ独立したコンパイル単位です（IEEE 1800-2023 3.12.1）。 モジュールや package の外にあるパラメータ、型、サブルーチン、変数、import は、そのファイルのモジュールを 囲むスコープ <code>$unit</code> になります。モジュールからは、自身の宣言と import の次に、それより前に宣言された コンパイル単位の項目と import、およびコンパイル単位のすべてのサブルーチンが見えます。<code>$unit::x</code> は コンパイル単位の項目 <code>x</code> を指します。コンパイル単位の変数は、そのファイルのモジュールが共有する 1 つの オブジェクトで、package 変数と同じく <code>$unit::v</code> という名前になります。これを宣言できるソースファイルは 1 つだけです。コンパイル単位での DPI import は未対応です。</p><h3 id="ブロックローカル変数" tabindex="-1">ブロックローカル変数 <a class="header-anchor" href="#ブロックローカル変数" aria-label="Permalink to &quot;ブロックローカル変数&quot;">​</a></h3><p>ブロックローカル変数は、<code>always_comb</code> と <code>always_ff</code> で字句スコープを持ちます。 モジュールの信号と同名の変数や、別のブロック・プロセスでの同名変数を扱えます。</p><h3 id="hard-packed-untagged-union" tabindex="-1">hard packed untagged union <a class="header-anchor" href="#hard-packed-untagged-union" aria-label="Permalink to &quot;hard packed untagged union&quot;">​</a></h3><p>hard packed untagged union のメンバーは、同じビットベクタを共有します。 全メンバーの幅が一致する必要があります（IEEE 1800-2023 7.3.1）。</p><h3 id="名前付きサブルーチン引数" tabindex="-1">名前付きサブルーチン引数 <a class="header-anchor" href="#名前付きサブルーチン引数" aria-label="Permalink to &quot;名前付きサブルーチン引数&quot;">​</a></h3><p>名前付きサブルーチン引数は仮引数の名前で束縛し、入力の評価と出力のコピーアウトは ソースに書かれた順序で行います。式と文のどちらでも、ANSI宣言で既定値を持つ引数を省略できます。 既定値は使うときだけ、サブルーチンを宣言した外側のスコープで評価します（IEEE 1800-2023 13.5.3）。 パラメータ初期値・範囲・generate条件の定数呼び出しも仮引数名で束縛し、generate内の宣言は自身のシグネチャを使います。 選択の添字での副作用を伴う名前付き呼び出しは拒否します。</p><h3 id="型付きパラメータパターン" tabindex="-1">型付きパラメータパターン <a class="header-anchor" href="#型付きパラメータパターン" aria-label="Permalink to &quot;型付きパラメータパターン&quot;">​</a></h3><p>型付きパラメータパターンは呼び出し元の型で変換し、幅・符号・4-state の値を保持します （IEEE 1800-2023 10.9、6.20.2）。packed 値はビット列として渡すため、子の構造体の メンバー名やフィールド分割が異なっても扱えます。型付き scalar パターンは、既定値が 通常の値であるパラメータも上書きできます。unpacked パターンは配列の位置と形状を保持します。</p><h3 id="ラッチ" tabindex="-1">ラッチ <a class="header-anchor" href="#ラッチ" aria-label="Permalink to &quot;ラッチ&quot;">​</a></h3><p>明示的な <code>always_latch</code> と通常の <code>always @*</code> は、ブロッキング代入による値の保持に対応します。 SystemVerilog と Veryl の <code>always_comb</code> の不完全な代入は、共通の <a href="./celox-toml.html#diagnostics"><code>[diagnostics]</code> 設定</a> で <code>inferred_latch = &quot;warn&quot;</code> または <code>&quot;allow&quot;</code> を指定すると値を保持します。既定は <code>error</code> です。 Rust の <code>.allow_inferred_latches(true)</code> と JavaScript の <code>allowInferredLatches: true</code> も利用できますが、明示した診断設定が優先されます。 通常の <code>eval_comb</code> と <code>initial</code> テストベンチの両方で 使用でき、ゲートが開いている間はデータの変化が出力に伝わり、閉じると直前の値を保持します。 4状態モードの未初期化ラッチは X で始まります。手続き型 <code>if</code> の条件が X または Z の場合は、真側を実行しません。</p><p><code>always_comb</code> と <code>always_latch</code> は時刻 0 にも一度実行します。<code>always @*</code> は 感度リストの入力変化を待ちます。これには <code>initial</code> ブロックや連続代入による変化も含みます。 同じ入力で <code>eval_comb</code> を繰り返しても再実行しません。<code>always_comb</code> と同様に、書き込む式は <code>always_latch</code> の 感度リストから除外します（IEEE 1800-2023 9.2.2.2、9.2.2.3）。プロセス間の フィードバックには従来どおり明示的なループ設定が必要です。このオプションは、 明示的な算術フィードバックに対する Veryl アナライザーのエラーを抑制しません。 <code>bus[0]</code> のような選択を読む場合、<code>always @*</code> は変数全体を監視し、 <code>always_comb</code> と <code>always_latch</code> は静的に特定できる最長の接頭部を監視します。 後者は呼び出した関数本体の読み取りも含みますが、task 呼び出しは引数の式だけが 感度に寄与します（IEEE 1800-2023 9.4.2.2、9.2.2.2.1）。 ノンブロッキング代入（<code>&lt;=</code>）には NBA スケジューリングが必要であり、推論を許可しても未対応です。</p><h3 id="timing-semantics" tabindex="-1">イベント待ちとレベル待ち <a class="header-anchor" href="#timing-semantics" aria-label="Permalink to &quot;イベント待ちとレベル待ち {#timing-semantics}&quot;">​</a></h3><ul><li>イベント制御は、開始した後に起きた変化を待ちます（IEEE 1800-2023 9.4.2）。 <code>a = 1; @(a ^ b);</code> の <code>a</code> への書き込みはこの待ちのイベントにならず、 その後に <code>a</code> か <code>b</code> が変化したときに再開します。 Icarus 13.0 は先の書き込みで起床し、Verilator 5.052 は Celox と同じ結果になります。</li><li>複数ビットの式の <code>posedge</code> / <code>negedge</code> は最下位ビットで判定します（Table 9-2）。 <code>@(posedge v)</code> は <code>v[3]</code> を無視し、<code>@(posedge v[3])</code> は <code>v[3]</code> に従います。 X / Z を経由する遷移も同表に従い、<code>0</code> から <code>x</code> は <code>posedge</code> です。</li><li>継続代入、組み合わせ回路のプロセス、イベント式は、書き込んだプロセスがタイミング制御に 達するか終了した時点でその書き込みを参照します。<code>b = 1; a = 1;</code> の後でも <code>a ^ b</code> は 変化しておらず、パルス <code>a = 1; a = 0;</code> は <code>@(a)</code> を起こしますが <code>@(a ^ b)</code> は起こしません。 パルスを見せるには書き込みの間に <code>#0</code> を入れてください。この順序は IEEE 1800-2023 4.7 で 許されています。Icarus は書き込みごとに式を評価します。</li><li><code>always_comb</code>、<code>always @*</code>、エッジで起動する <code>always</code>、<code>always_ff</code> の1回の評価が書いた値は、 後の書き込みで上書きされるものも含めてすべて待ち側から見えます。<code>a</code> が 1 のとき、 <code>y = 0; if (a) y = 1;</code> は <code>@(y)</code> を起こします（IEEE 1800-2023 4.3、9.4.2）。ノンブロッキングの 更新は NBA 領域で発行順に適用し、それぞれが1回の更新です（10.4.2）。子モジュールの出力ポートは 親のネットへの継続代入なので（23.3.3）、親の待ちは前の項目と同じく確定した値だけを見ます。 Verilator 5.052 は評価の最終値だけを見ます。Icarus 13.0 はポートを通したパルスも見ます。</li></ul><h3 id="変数の寿命" tabindex="-1">変数の寿命 <a class="header-anchor" href="#変数の寿命" aria-label="Permalink to &quot;変数の寿命&quot;">​</a></h3><p>変数の寿命は IEEE 1800-2023 6.21 に従います。クラス外のプロセスのブロック、関数、タスクの中で宣言した 変数は、その変数自身、そのサブルーチン、またはそのモジュール（<code>module automatic</code>）が <code>automatic</code> と宣言されていない限り static です。クラスメソッドの寿命は automatic です（8.6）。 ブロックの static なローカル変数は、ブロックの実行をまたいで値を 保持し、初期化子は時刻 0 に 1 回だけ実行します。<code>always_ff</code> 内の <code>int count; count++;</code> は数を数えます。 automatic なローカル変数は、ブロックに入るたびに初期化します。どの経路でも読む前に書き込むため、入った 時点の値が読まれない static なローカル変数は、どちらでも同じ動作です。static なローカル変数は値を保持する ため、一部の経路でしか書き込まない <code>always_comb</code> のローカル変数はラッチになり、ほかの暗黙のラッチと同じく <code>inferred_latch</code> の緩和が必要です。</p><p>関数の static ローカル変数と戻り値は、呼び出しをまたいで値を保持します（13.4.2）。 スカラーの <code>real</code> と packed／unpacked な整数の保存領域に対応しています。automatic 関数内で 明示的に <code>static</code> とした変数も共有され、automatic 変数は呼び出しごとに初期化されます。 static な output 引数も、代入しない経路では以前の値を保持します。保持が必要な領域は呼び出し位置と 時間待ちプロセスの間で共有され、モジュール内の領域はインスタンスごとに独立します。 宣言の初期化子は、関数が未呼び出しでも時刻 0 に一度だけ実行します。状態を保持する関数を 呼び出す初期化子は、初期化プロセスを実行する <code>Simulation</code> または native testbench が必要です。 定数関数としての呼び出しは 毎回新しい値を使い、実行時の状態に影響しません（13.4.3）。</p><p>値を保持する task ローカル変数と、定数でない static 初期化子は引き続き未対応です。 これらには <code>automatic</code> を指定してください。package 関数の状態には、複数の手続きドライバーに関する 既存の package 変数の制約が適用されます。既定の寿命（<code>interface automatic</code>）が 使用先のモジュールと異なる interface は拒否します。</p><h3 id="実行時のループ" tabindex="-1">実行時のループ <a class="header-anchor" href="#実行時のループ" aria-label="Permalink to &quot;実行時のループ&quot;">​</a></h3><p>反復回数が実行時の値で決まる <code>always_ff</code> 内のループは、生成コード内の ループとして実行します。進まなくなったループは、ループ変数を示す実行時エラーを報告します。</p><h3 id="文として呼び出したシステム関数" tabindex="-1">文として呼び出したシステム関数 <a class="header-anchor" href="#文として呼び出したシステム関数" aria-label="Permalink to &quot;文として呼び出したシステム関数&quot;">​</a></h3><p>文として呼び出したシステム関数（<code>$countones(f(a));</code> など）は、式の中の同じ呼び出しと 同様に検査・評価し、値を捨てます。<code>$bits</code> と <code>$size</code> は被演算子を評価しません。</p><h3 id="定数関数" tabindex="-1">定数関数 <a class="header-anchor" href="#定数関数" aria-label="Permalink to &quot;定数関数&quot;">​</a></h3><p>定数関数は、呼び出す表示タスクと重大度タスクを無視します。</p><h3 id="readmemh-readmemb" tabindex="-1"><code>$readmemh</code> / <code>$readmemb</code> <a class="header-anchor" href="#readmemh-readmemb" aria-label="Permalink to &quot;`$readmemh` / `$readmemb`&quot;">​</a></h3><p><code>$readmemh</code> / <code>$readmemb</code> は、デザインのコンパイル時にファイルを読みます。ファイルが ないか不正な場合は <code>MemoryFile</code> エラーです。<code>always_ff</code> では起動のたびにファイルの各ワードを 書き込み、<code>initial</code> では初期状態の一部になります。明示した範囲はどちらの向きにも読み込み、 ファイル中の <code>@</code> アドレスは配列の絶対インデックスです。要求範囲外のアドレス指定はエラーです。 アドレス指定がなくワード数が範囲と合わない場合はコンパイル警告（<code>Simulator::warnings()</code>）に なり、余ったワードは無視され、足りない分のメモリは変わりません。</p><h3 id="バイナリ入力" tabindex="-1">バイナリ入力 <a class="header-anchor" href="#バイナリ入力" aria-label="Permalink to &quot;バイナリ入力&quot;">​</a></h3><p><code>$fread</code> はバイト列をビッグエンディアン順で packed 整数または1次元の静的な 整数メモリへ読み込みます（IEEE 1800-2023 21.3.4.4）。メモリは既定で最小の 添字から昇順に読み込み、開始位置と要素数を省略可能な引数で指定できます。 packed 整数ではこれらの引数を無視します。部分的な読み込みでは、入力を 受け取らなかったビットとその X/Z を保持します。戻り値は読み込んだバイト数、 I/O エラー時はゼロです。</p><h3 id="バイト入力とファイル位置" tabindex="-1">バイト入力とファイル位置 <a class="header-anchor" href="#バイト入力とファイル位置" aria-label="Permalink to &quot;バイト入力とファイル位置&quot;">​</a></h3><p><code>$fgetc(fd)</code> は次のバイトを0〜255の整数で返し、EOF またはエラーでは -1 を返します。 <code>$ungetc(character, fd)</code> はファイルを書き換えずに1バイトを戻し、成功時0、失敗時 -1 を 返します。pushback は1バイトに対応します。<code>$feof(fd)</code> は以前の読み取りで EOF に 達したかを調べます。最後のバイトを読んだだけでは EOF になりません。成功した pushback と位置変更は EOF を解除します。</p><p><code>$ftell(fd)</code> は pushback を考慮したバイト位置を返し、エラーまたは符号付き32ビットの 範囲を超える位置では -1 を返します。<code>$fseek(fd, offset, operation)</code> は符号付き32ビットの offset を使い、先頭（0）、現在位置（1）、末尾（2）を基準に移動します。<code>$rewind(fd)</code> は 先頭に戻します。位置変更は成功時0、失敗時 -1 を返し、成功すると pushback を破棄します。 <code>$fflush(fd_or_mcd)</code> は指定した出力先を、<code>$fflush()</code> は開いている全ファイルを flush します。 無効な flush descriptor は実行時エラーです。これらは時間付き <code>Simulation</code> で実行し、 入力と位置変更には file descriptor を使います。</p><h3 id="書式付き入力" tabindex="-1">書式付き入力 <a class="header-anchor" href="#書式付き入力" aria-label="Permalink to &quot;書式付き入力&quot;">​</a></h3><p><code>$sscanf(source, format, outputs...)</code> と <code>$fscanf(fd, format, outputs...)</code> は 整数の <code>%d</code>、<code>%h</code> / <code>%x</code>、<code>%o</code>、<code>%b</code>、<code>%c</code> と実数の <code>%e</code> / <code>%f</code> / <code>%g</code> 変換、 数値フィールド幅、代入抑制、 リテラル照合と空白を扱います（IEEE 1800-2023 21.3.4.3）。入力と書式には 文字列リテラルまたは packed 整数を使用できます。戻り値は代入した出力の数で、 照合できなかった出力は保持します。実数変換は <code>real</code>、<code>realtime</code>、<code>shortreal</code> に対応し、 符号・小数点・指数部を扱います。<code>shortreal</code> は直接 binary32 に丸め、オーバーフローは 符号付き無限大となり、負のゼロも保持します。符号だけの入力や不完全な指数部は 出力を変更せず失敗します。整数変換には整数、実数変換には実数の宛先が必要です。 文字列出力の <code>%s</code>、時間倍率を扱う <code>%t</code> は未対応です。 両関数とも timed <code>Simulation</code> で実行します。 <code>$sscanf</code> はチェックポイントに対応し、外部ファイルを使う <code>$fscanf</code> は拒否します。</p><h3 id="実行時のファイル出力" tabindex="-1">実行時のファイル出力 <a class="header-anchor" href="#実行時のファイル出力" aria-label="Permalink to &quot;実行時のファイル出力&quot;">​</a></h3><p><code>$fopen</code>、<code>$fclose</code>、<code>$fdisplay</code> / <code>$fwrite</code> とその <code>b</code> / <code>o</code> / <code>h</code> 形は、 時間を持つ <code>Simulation</code> で実行します（IEEE 1800-2023 21.3）。引数が1個の <code>$fopen</code> は multichannel descriptor を返し、OR で複数の出力先を選べます。 ビット0は標準出力です。モードを指定すると file descriptor を返します。 閉じたチャネルは再利用され、オープン失敗は0を返します。無効な descriptor や 書き込み失敗は実行時エラーです。ファイル名とモードは文字列リテラルまたは 整数の packed 文字列を指定できます。パスは UTF-8 に限定し、相対パスはホスト プロセスの作業ディレクトリを基準とします。動的な <code>string</code> 値は未対応です。</p><p><code>$writememh</code> / <code>$writememb</code> は呼び出し時点の静的 unpacked 配列を、既存ファイルを 上書きして出力します（21.5）。実行時の開始・終了アドレスで順方向・逆方向を 指定でき、範囲外は実行時エラーです。X/Z を保持し、アドレス指示子は出力しません。 動的配列と連想配列は未対応です。既存の <code>$readmemh</code> / <code>$readmemb</code> は引き続き コンパイル時に読み込みます。</p><p>これらを直接またはサブルーチン経由で呼ぶエッジプロセスには <code>Simulation</code> が必要で、 <code>Simulator</code> のビルダーはエラーを返します。組み合わせプロセスからの呼び出しは未対応です。</p><h3 id="集約型の定数パラメータ" tabindex="-1">集約型の定数パラメータ <a class="header-anchor" href="#集約型の定数パラメータ" aria-label="Permalink to &quot;集約型の定数パラメータ&quot;">​</a></h3><p>集約型の定数パラメータ（unpacked 配列や、パターンで与える packed 構造体）は、 シミュレーション開始時から値を保持する変数です。エラボレーション時の定数が必要な場所では 使えません。</p><h3 id="シミュレーションの一時停止" tabindex="-1">シミュレーションの一時停止 <a class="header-anchor" href="#シミュレーションの一時停止" aria-label="Permalink to &quot;シミュレーションの一時停止&quot;">​</a></h3><p><code>initial</code> ブロックの <code>$stop</code> はシミュレーションを一時停止します（IEEE 1800-2023 20.2）。 <code>Simulation::step</code> と <code>run_until</code> は停止した時刻で戻り、<code>is_stopped()</code> が真になります。 その時刻の他のプロセスは待機し、次の呼び出しでループや関数の中も含めて <code>$stop</code> の 直後から再開します。停止した時刻の処理は、停止前にプロセスが起こしたエッジも保ったまま 再開します。停止中はチェックポイントと状態ファイルを作れません（<code>CheckpointError::Stopped</code>）。 <code>always</code> 系のプロセスでは、<code>$finish</code> が <code>RuntimeEvent::Finish</code> に なるのと同様に <code>RuntimeEvent::Stop</code> として報告します。診断レベルの引数では何も 表示しません。VPI ホストのように対話モードを持たないバッチ実行では <code>$stop</code> で終了します。 <code>$exit</code> は呼び出した program ブロックの initial 手続きを終了します（24.7）。 Celox は program ブロックを持たず、それ以外からの呼び出しは 24.7 の規定どおり無視し、 その呼び出し位置でコンパイル警告（<code>Simulator::warnings()</code>）を出します。定数関数内の呼び出しも同様です。 関数宣言内の呼び出しは、その関数を使わなくても警告します。定数評価が実行したかどうかには依存しません。</p><h3 id="実行時-i-o-と-plusargs" tabindex="-1">実行時 I/O と plusargs <a class="header-anchor" href="#実行時-i-o-と-plusargs" aria-label="Permalink to &quot;実行時 I/O と plusargs&quot;">​</a></h3><p><code>initial</code> やエッジで起動する <code>always</code> / <code>always_ff</code> と、そのサブルーチンからの ホスト I/O には <code>Simulation::from_sv_sources</code> を使います。組合せプロセスからは 未対応です。時間付き実行が必要なエッジプロセスを <code>Simulator</code> で構築するとエラーになります。</p><p>引数は <code>.plusargs([&quot;+COUNT=12&quot;, &quot;+TRACE&quot;])</code> で順序を保って渡します。 <code>$test$plusargs</code> は前方一致で検索し、<code>$value$plusargs</code> は整数変換と packed 整数変数への <code>%s</code> を扱います。最初に一致した引数を使い、未一致の場合は書き込み先の値を保持します。 real 変換と動的 string は未対応です。</p><p>ファイル descriptor とメモリ書き出しは<a href="#実行時のファイル出力">実行時のファイル出力</a>を参照してください。</p><p><a href="./vcd.html#systemverilog-source-controls">VCD 制御</a>の記録開始は、その時刻の状態が確定した後です。 ファイル I/O または SV からの VCD 制御を含むデザインでは、ホスト側の状態を保存できないため、 checkpoint と状態ファイルの保存・復元はエラーになります。</p><p><code>$dist_uniform(seed, start, end)</code> は Annex N の一様分布を使い、整数の seed 変数を更新します。 両端を含み、境界が同じ値か逆順なら seed を進めず <code>start</code> を返します。</p><p><code>$dist_normal</code>、<code>$dist_exponential</code>、<code>$dist_poisson</code>、<code>$dist_chi_square</code>、 <code>$dist_t</code>、<code>$dist_erlang</code> は時間付き <code>Simulation</code> のプロセスとそのサブルーチンで Annex N の分布を使います。引数と戻り値は符号付き32ビット整数です。 整数の inout seed は int に変換し、添字付き要素の場合も一度だけ書き戻します。 指数・Poisson分布の mean、カイ二乗・t分布の自由度、Erlang分布の両引数は正値が必要です。 不正な値は seed を更新せず実行時エラーとして診断します。正規分布の mean と標準偏差は 任意の整数を受け付けます。SV の <code>real</code> 型は必要ありません。seed はデザインの状態なので、 checkpoint の復元で乱数列を再現できます。</p><h2 id="time-and-precision" tabindex="-1">時刻と精度 <a class="header-anchor" href="#time-and-precision" aria-label="Permalink to &quot;時刻と精度 {#time-and-precision}&quot;">​</a></h2><p><code>$timeunit</code> と <code>$timeprecision</code> は秒を基準とする指数を32ビットの符号付き整数で 返します（IEEE 1800-2023 20.4.1）。現在の時間スコープ、<code>$unit</code>、<code>$root</code>、 別ファイルを含むスカラーのモジュールインスタンス階層を解決します。 <code>timeunit</code>、<code>timeprecision</code>、先行する <code>timescale</code>、<code>resetall</code> の優先順位は 3.14.2.3に従い、デフォルトは1 ns / 1 psです。グローバル精度には、 インスタンス化されていない定義も含め、すべての精度宣言とディレクティブの精度を 使用します（3.14.3）。インスタンス配列の選択とgenerate階層は、展開後の階層検索が 必要なため、現在は未対応として診断します。</p><p>時間単位と精度は、他のスコープ項目より前で別々に宣言でき、同じ値の宣言は 後でも繰り返せます。明示指定・継承による設定とデフォルトがデザイン内で混在する 場合は診断します（3.14.2.3）。モジュール定義とパッケージは、同名でもそれぞれの 時間単位と精度を保持します（3.13）。同名のモジュールがインスタンス化されていても、 パッケージ名による問い合わせを解決します。ルートを含む階層インスタンスが見つかった 場合は、同名パッケージより優先します。シミュレータのルート検索は選択したトップと 到達可能な階層を使用し、未使用module内のインスタンス化で選択したルートを隠しません。 時間リテラルの整数・固定小数点表記では、 先頭ゼロを含めた数値を解釈します。interfaceの関数は、展開でモジュールに コピーされた後も、宣言元の時間スコープとコンパイル単位を使用します。 スカラーのinterfaceインスタンス・ポートへの問い合わせは、展開前にバインドされた interface型から解決します。generic interfaceポートとgenerate内のローカルハンドルも 対象です。<code>child.info</code>のように子module内のinterfaceインスタンスを指定する スカラー階層も、インスタンスが展開で消える前に解決します。</p><p><code>Simulation</code> は設計全体の時間精度（IEEE 1800-2023 3.14.3）で時刻を数えます。 既定は 1 ps で、<code>run_until(1000)</code> は 1 ns まで進めます。時間単位が 1 ns の モジュールの <code>#10</code> は 10,000 ps 待ちます（3.14.1）。<code>$time</code> は呼び出した スコープの時間単位で表した時刻を整数に丸めて返し、半分は切り上げます（20.3.1）。 パッケージの関数ではそのパッケージの時間単位を使います。<code>$stime</code> はその値の 下位32ビットを返します（20.3.2）。組合せ回路は入力が変わったときに時刻を読み、 時刻だけが進んでも評価し直しません。時刻を持たない <code>Simulator</code> では0を返します。 <code>$realtime</code> は呼び出し元の時間単位で整数への丸めなしに <code>real</code> を返します（20.3.3）。 たとえば時間単位が1 nsのスコープで1.25 ns時点では、<code>$realtime</code> は1.25、 <code>$time</code> は1を返します。<code>real</code> は IEEE 754 倍精度のため、大きな時刻では 変換時に精度を失う場合があります。checkpoint の復元後は復元した時刻を参照します。</p><p><code>$printtimescale</code> は IEEE1800-2023 20.4.2 の形式で時刻スコープを表示します。 例: <code>Time scale of (Top.child) is 100ns / 10ps</code>。 引数なしの現在スコープ、design element、<code>$unit</code>、<code>$root</code> を指定でき、 <code>initial</code>、<code>always</code> 系のプロセスとサブルーチンで実行できます。 現在のモジュールと相対参照には実際のインスタンス階層名を使い、 package・interface の手続きは宣言元の時間単位と精度を保持します。</p><h2 id="random-numbers" tabindex="-1">乱数 <a class="header-anchor" href="#random-numbers" aria-label="Permalink to &quot;乱数 {#random-numbers}&quot;">​</a></h2><p><code>$urandom</code> は周期が2の32乗の決定的な線形合同法を使います （IEEE 1800-2023 18.13.1、18.14）。同じシードで同じ列を再現し、 シード引数は変更しません。サブルーチン内では呼び出し元プロセスの列を使い、 乱数状態はチェックポイントの保存・復元に含まれます。 既定シードと具体的な乱数値は実装依存です。 組み合わせプロセスでは、プロセスの起動時にだけ乱数列が進みます。 <code>always_comb</code> は時刻0と暗黙の感度リストの入力変化時に実行され、 <code>always @*</code> は入力変化を待ちます。入力が変わらない再評価では乱数列は進みません。 定数値を要求する文脈では診断を返します。</p><p><code>$urandom_range(maxval, minval)</code> は <code>$urandom</code> の列から両端を含む範囲の値を返し、 逆順の範囲は入れ替えます。<code>minval</code> の既定値は0です（18.13.2）。 <code>$random</code> は IEEE 1800-2023 附属書 N のアルゴリズムに従うため、 Icarus Verilog などそれを実装するシミュレータと同じ値を返します。 <code>$random(seed)</code> はシード変数を更新します。引数がなければプロセスごとのシードを 使い、その初期値は0です。そのため <code>$random</code> を呼ぶプロセスが1つだけの設計では、 設計全体で1つのシードを持つシミュレータと一致します。</p><h2 id="real-math" tabindex="-1">実数の数学関数 <a class="header-anchor" href="#real-math" aria-label="Permalink to &quot;実数の数学関数 {#real-math}&quot;">​</a></h2><p><code>$ln</code>、<code>$log10</code>、<code>$exp</code>、<code>$sqrt</code>、<code>$pow</code>、<code>$floor</code>、<code>$ceil</code>、<code>$sin</code>、 <code>$cos</code>、<code>$tan</code>、<code>$asin</code>、<code>$acos</code>、<code>$atan</code>、<code>$atan2</code>、<code>$hypot</code>、<code>$sinh</code>、 <code>$cosh</code>、<code>$tanh</code>、<code>$asinh</code>、<code>$acosh</code>、<code>$atanh</code> は real を引数と戻り値とし、 IEEE 1800-2023 20.8.2 の対応する C 数学関数に従います。整数と shortreal の引数は 呼び出し前に real に変換します。<code>$floor</code> と <code>$ceil</code> も real を返し、 <code>$atan2(y, x)</code> の引数順序を保持します。定義域や値域を超える場合は、対応する 浮動小数点の NaN や無限大を返します。</p><p>組み合わせ・クロック・時間付きプロセスで利用でき、引数が定数なら展開時に評価します （11.2.1）。入れ子の呼び出しと real パラメーターの精度を保持し、整数への代入や cast では 最終結果を変換します。すべてのシミュレーターバックエンドで同じ数学演算の評価処理を使います。</p><h2 id="mixed-language" tabindex="-1">Veryl と SystemVerilog の混在 <a class="header-anchor" href="#mixed-language" aria-label="Permalink to &quot;Veryl と SystemVerilog の混在 {#mixed-language}&quot;">​</a></h2><p><code>Simulator::from_mixed_sources</code>は両言語のソースを組み合わせます。トップはどちらの言語でもよく、 階層は Veryl → SV → Veryl のように言語境界を複数回跨げます。Veryl では <code>$sv::Module</code>、 SV からは Veryl のモジュールや interface を Veryl の emitter が出力する名前で参照します。 出力された SV に対して書いた SV コードがそのまま使えます。プロジェクト <code>prj</code> のモジュール <code>Module</code> は <code>prj_Module</code>、<code>Veryl.toml</code> で <code>omit_project_prefix</code> を設定した場合は <code>Module</code> です。 <code>Veryl.toml</code> がない場合のプロジェクト名は <code>prj</code> です。Veryl モジュールの出力名と同名の SV モジュールは 重複定義になります。Veryl のトップは Veryl の名前で指定します。数値パラメータは、それぞれの frontend が解決します。</p><p>interface と <code>input</code> / <code>output</code> modport のメンバー接続も双方向に対応します。SV の interface は Veryl で <code>inst bus: $sv::Bus;</code>、ポートで <code>bus: modport $sv::Bus::slave</code> と指定できます。 SV から Veryl の interface をインスタンス化し、両言語のモジュールに接続することもできます。 interface のパラメータ、インスタンス配列、SV の generic interface ポートは接続先の型で解決します。 Veryl からインスタンス化した SV interface の内部ロジックは、SV frontend で実行します。</p><p>パラメータの宣言幅が先行する interface パラメータに依存する場合も、SV側の名前付き上書きの順序にかかわらず、宣言順で上書きを反映します。 VerylとSVに同名のモジュールがある場合、<code>$sv::Module</code> はSV側の定義を選択します。 interface の既定値で呼び出す定数関数は、native analyzer が本体を式として表せる場合に宣言式へ展開します。 ループなど、本体を宣言式で表せないヘッダ依存の定数関数は、未対応として診断します。 引数型や戻り値型の幅がヘッダパラメータに依存する関数も、宣言式でその型変換を表せないため未対応として診断します。 宣言内のキャスト先のサイズがinterfaceパラメータに依存する場合や、定数関数をシンボリックに解析できない場合も、既定値で計算した結果を固定せず未対応として診断します。</p><p>両 frontend の宣言情報と解析結果を直接接続するため、Veryl の SV emitter は不要です。 言語境界を跨ぐ interface 関数の呼び出しと、関数の <code>import</code> / <code>export</code> modport は、まだ未対応です。 各言語内での対応範囲は従来どおりです。</p><h2 id="dpi-c-imports" tabindex="-1">DPI-C imports <a class="header-anchor" href="#dpi-c-imports" aria-label="Permalink to &quot;DPI-C imports {#dpi-c-imports}&quot;">​</a></h2><p><code>sv-dpi</code> Cargo feature は <code>systemverilog</code> を含み、<code>import &quot;DPI-C&quot;</code> による C 関数呼び出しを有効にします。 <code>dpi_function</code> または <code>dpi_library</code> で関数を登録します。どちらも C 側の型との一致を呼び出し側が保証する <code>unsafe</code> API です。</p><p>対応するのは、モジュール・package で宣言した関数を <code>always_ff</code> とそこから呼ぶ関数で使う場合です。 最大16個の <code>input</code> 引数を扱い、型は <code>bit</code>、<code>logic</code>、<code>byte</code>、<code>shortint</code>、<code>int</code>、<code>longint</code>（符号付き・符号なし）、戻り値はそれらか <code>void</code> です。 組み合わせ回路からの呼び出し、<code>context</code>、task import、export、<code>output</code> / <code>inout</code>、packed vector、<code>real</code>、<code>string</code> などは未対応です。</p><p>登録のコード例と詳細は<a href="/celox/guide/systemverilog-reference.html#dpi-c-imports">英語版の DPI-C imports</a>を参照してください。</p><h2 id="systemverilog-emitted-by-veryl" tabindex="-1">Veryl が出力する SystemVerilog <a class="header-anchor" href="#systemverilog-emitted-by-veryl" aria-label="Permalink to &quot;Veryl が出力する SystemVerilog {#systemverilog-emitted-by-veryl}&quot;">​</a></h2><p>Veryl の適合性スイートは、Veryl が出力する SystemVerilog に対しても実行します。対象外として 残るケースは次のとおりです。</p><ul><li>位置指定の要素と <code>default:</code> を混在させた配列リテラル（<code>&#39;{a, default: b}</code>）に対して、Veryl は不正な SystemVerilog を出力します。</li><li>Celox の Veryl フロントエンドは、<code>always_ff</code> 内での出力引数や副作用を持つ関数呼び出しを オプトインで扱えますが、Veryl 自身はこれを拒否します。出力される SystemVerilog の呼び出し では、Veryl のノンブロッキングの意味ではなく即座にコピーアウトされてしまうためです。 こうしたデザインには対応する SystemVerilog がなく、出力されません。</li><li>テストベンチ用のモジュール（クロックや <code>$finish</code> のスケジューリングを伴う <code>initial</code> ブロック、階層代入）は、シミュレーション可能な SystemVerilog モジュールとして 出力されません。</li></ul>',119)])])}const m=o(t,[["render",r]]);export{u as __pageData,m as default};
